FLAGS={'benchmark_accepted':False,'champion_promoted':False,'new_submission':False,'official_SOTA_verified':False,'official_rank':None,'benchmark_generalization_claim':False}
def custody_from_report(report):
 if report is None:return {'semantic_label_decodes':None,'decode_attempted_tokens':None,'semantic_decode_count_uncertain':True,'label_reader_calls':None,'scope':'No complete authenticated gold-stage report; absence never implies zero.'}
 I.envelope(report);count=report['semantic_labels_decoded'];attempted=report['decode_attempted_tokens'];uncertain=report['semantic_decode_count_uncertain'];I.require((count is None or type(count)is int and 0<=count<=12)and(attempted is None or type(attempted)is int and 0<=attempted<=12)and type(uncertain)is bool,'EXACT_PARTIAL_GOLD_COUNTS_REQUIRED');I.require(count is None or attempted is None or count<=attempted,'PARTIAL_GOLD_COUNT_ORDER');return {'semantic_label_decodes':count,'decode_attempted_tokens':attempted,'semantic_decode_count_uncertain':uncertain,'label_reader_calls':report['label_reader_calls'],'gold_join_status':report['status'],'scope':'Counts retained verbatim from authenticated once-only gold stage; no decoding/retry/inference.'}
def replay(plan,plan_sha,actual_execution,evidence,custody,errors,evaluation_executed=False):
 return {'schema_version':1,'epoch':40,'kind':I.KIND,'phase':'dev','source_checkpoint':I.SOURCE,'source_plan_sha256':plan_sha,'status':'REJECTED_DEV_INTEGRITY','checks_passed':False,'dev_passed':False,'evaluation_executed':evaluation_executed,'metrics':None,'gate_checks':{k:'NOT_EVALUATED'for k in M.gate_names()},'data_roles':plan['data_roles'],'arms':M.ARMS,'primary':M.PRIMARY,'reference':M.REFERENCE,'all_cases_retained_denominator':12,'benchmark_accuracy':None,'used_confirmation_identities':[],'label_custody':custody,'actual_execution':actual_execution,'evidence':evidence,'errors':errors,'no_model_performance_conclusion':True,'no_gold_retry_remap_drop_or_replacement':True,**FLAGS}
def capture_failure(admission_ref,project):
 """Root authorizes metadata capture, never gold access or new execution."""
 a=I.load_ref(admission_ref,project);I.envelope(a);I.require(type(a['failure_reason_code'])is str and re.fullmatch('[A-Z0-9_]{1,128}',a['failure_reason_code']),'SAFE_FROZEN_FAILURE_REASON_ENUM_REQUIRED');I.require(a['source_checkpoint']==I.SOURCE and a['root_metadata_failure_capture_authorized']is True,'ROOT_FROZEN_FAILURE_ADMISSION_REQUIRED');refs=a['evidence'];I.require(set(refs)=={'plan','raw','execution','dispatch','physical_closure','source_admission','gold_join_report','joined_labels'},'EXPLICIT_OPTIONAL_FAILURE_REFERENCE_SCHEMA');plan=I.load_ref(refs['plan'],project);I.envelope(plan);ps=refs['plan']['sha256'];I.require(a['source_plan_sha256']==ps,'FAILURE_PLAN_REFERENCE_MISMATCH');source=I.load_ref(refs['source_admission'],project);I.envelope(source);I.require(source['checks_passed']is True and source['verified_actual_remote_readback']is True and source['plan_sha256']==source['source_plan_sha256']==ps,'ACTUAL_SOURCE_ADMISSION_BEFORE_FAILURE_CAPTURE');proof=I.load_ref(refs['physical_closure'],project);I.envelope(proof);I.require(proof['source_plan_sha256']==ps and proof['physical_closure_passed']is True and proof['physical_supervisor_closed']is True and proof['unknown_physical_ownership']is False and proof['owned_worker_group_members']==[],'KNOWN_FULL_PHYSICAL_CLOSURE_BEFORE_FAILURE_CAPTURE');dispatch=I.load_ref(refs['dispatch'],project);I.envelope(dispatch);I.require(dispatch['plan_sha256']==ps,'DISPATCH_PLAN_MISMATCH');raw=I.load_ref(refs['raw'],project)if refs['raw']is not None else None;execution=I.load_ref(refs['execution'],project)if refs['execution']is not None else None;gold=I.load_ref(refs['gold_join_report'],project)if refs['gold_join_report']is not None else None
 if refs['joined_labels']is not None:I.read_ref(refs['joined_labels'],project) # bytes/hash only, never parse labels in failure path
 custody=custody_from_report(gold);actual={'worker_attempts':1,'logical_native_budget_reserved':1,'worker_attempt_count_scope':'Authenticated dispatch reservation, not an inferred successful worker start.','actual_verified_worker_starts':None,'owned_live_processes_closed':True,'known_corpus_batches_attempted_at_last_capture':None,'known_corpus_batches_completed_at_last_capture':None,'captured_actual_counters':None,'source_of_actual_counts':'UNKNOWN_WITHOUT_FINAL_RAW'}
 if raw is not None:
  I.envelope(raw);I.require(raw['plan_sha256']==ps,'RAW_PLAN_MISMATCH');c=raw.get('counters');I.require(c is None or type(c)is dict,'EXPLICIT_COUNTERS_OR_UNKNOWN');actual['captured_actual_counters']=c;actual['source_of_actual_counts']='Authenticated retained raw capture, not inferred zeros'
  if c is not None:
   for src,dst in [('corpus_batches_attempted','known_corpus_batches_attempted_at_last_capture'),('corpus_batches_completed','known_corpus_batches_completed_at_last_capture')]:
    value=c.get(src);actual[dst]=value if type(value)is int and value in[0,1]else None
 if execution is not None:I.envelope(execution);I.require(execution['plan_sha256']==ps,'EXECUTION_PLAN_MISMATCH');actual['captured_supervisor_status']=execution.get('status');actual['actual_verified_worker_starts']=execution.get('verified_worker_starts');actual['recorded_wall_seconds_including_init_cleanup']=execution.get('wall_seconds_including_init_cleanup')
 return replay(plan,ps,actual,{'failure_admission':admission_ref,**refs},custody,[{'code':a['failure_reason_code'],'scope':'Frozen metadata-only failure path. No EVALUATE, original oracle/retained label parse, remap, retry, replacement or model-performance inference.'}],False)
